// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 prevBalance, uint256 depositAmount, uint48 unlockTime) public {
        address sender = address(0x1234);
        // admissible: previous balance + deposit must not revert in correct version (overflow check)
        // We also constrain prevBalance to a value that an attacker could hold, and depositAmount >0.
        vm.assume(depositAmount > 0.0001 ether);
        vm.assume(prevBalance + depositAmount < type(uint256).max);
        vm.assume(prevBalance > 0.0001 ether);
        // set up sender with previous balance by faking a Put
        vm.deal(sender, prevBalance);
        vm.prank(sender);
        c.Put{value: prevBalance}(uint256(unlockTime));
        // record balance before the test call
        uint256 beforeBalance = c.Acc(sender);
        // send extra ether for the test deposit
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        bool ok;
        try c.Put{value: depositAmount}(uint256(unlockTime)) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 afterBalance = c.Acc(sender);
        // If the call succeeded (ok==true) then the balance must have increased exactly by depositAmount, which implies no overflow
        assertTrue(!ok || afterBalance == beforeBalance + depositAmount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, uint256 putAmount, uint256 unlockTime) public {
        // Bound values to reasonable ranges, but still allow overflow scenarios.
        // initialBalance up to type(uint256).max to allow overflow tests.
        // putAmount up to type(uint256).max to allow overflow tests.
        // Put requires msg.sender has an address; we'll use address(this) as the sender.
        address sender = address(this);

        // Set up the initial balance of the sender in the Acc mapping.
        // We need to call Put first with some value to set the balance.
        // We can do that by calling Put with initialBalance as msg.value, starting from empty account.
        vm.deal(sender, initialBalance);
        vm.prank(sender);
        try c.Put{value: initialBalance}(unlockTime) {
            // If overflow check passes, balance is set. For buggy, this might overflow silently.
        } catch {
            // If revert, the initial setup failed. But we need a balance to test the overflow condition.
            // Skip this test run if we can't set up.
            vm.assume(false);
        }

        // Now record the balance before the second Put.
        (uint256 beforeUnlockTime, uint256 beforeBalance) = c.Acc(sender);

        // Now perform the second Put with putAmount.
        vm.deal(sender, putAmount);
        vm.prank(sender);
        try c.Put{value: putAmount}(unlockTime) {
        } catch {
            // If the Put reverts, we can't test the overflow condition further.
            vm.assume(false);
        }

        // After the second Put, get the new balance.
        (uint256 afterUnlockTime, uint256 afterBalance) = c.Acc(sender);

        // The general rule: after a successful Put, the balance must be at least the previous balance
        // because balance = prevBalance + msg.value, and addition in uint256 should not decrease.
        // In the correct contract, overflow is prevented by require, so this always holds.
        // In the buggy contract, overflow can cause afterBalance < beforeBalance.
        assertTrue(afterBalance >= beforeBalance, "Overflow violation: balance decreased after Put");
    }
}

