pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint256 _msgValue) public {
        // Keep the domain wide; only bound msg.value to reasonable range (not constraining the overflow possibility)
        vm.assume(_msgValue > 0);
        vm.assume(_unlockTime <= type(uint256).max / 2);

        address sender = address(0x1234);
        vm.deal(sender, type(uint256).max);

        // Record balance before Put
        uint256 prevBalance = c.Acc(sender).balance;

        vm.prank(sender);
        c.Put{value: _msgValue}(_unlockTime);

        // After Put, balance must be >= previous balance
        uint256 newBalance = c.Acc(sender).balance;
        assertTrue(newBalance >= prevBalance, "balance must not decrease after Put");
    }
}

