pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        // bound amount to prevent overflow revert in require check (but keep it wide)
        amount = bound(amount, 0, type(uint256).max / 2);
        // bound unlockTime to a wide range around current block.timestamp
        uint256 now = block.timestamp;
        vm.assume(unlockTime <= now + 365 days);
        vm.assume(unlockTime >= (now > 365 days ? now - 365 days : 0));

        // fund and call Put
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.Put{value: amount}(unlockTime);

        // core invariant: after Put, caller's unlockTime must be >= current block.timestamp
        uint256 storedUnlockTime = c.Acc(caller).unlockTime;
        assertTrue(storedUnlockTime >= block.timestamp);
    }
}

