pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 putValue, uint256 collectAmt, uint256 warpTime) public {
        // Restrict to admissible ranges: putValue > 0 so we have a balance; collectAmt <= putValue so Collect is possible;
        // warpTime between _unlockTime and block.timestamp of the Put.
        vm.assume(_unlockTime < type(uint256).max);
        vm.assume(putValue > 0);
        vm.assume(collectAmt <= putValue);

        address actor = address(0x1000);
        vm.deal(actor, putValue);

        // Record block.timestamp at time of Put
        vm.prank(actor);
        c.Put{value: putValue}(_unlockTime);
        uint putBlockTs = block.timestamp;

        // Ensure warpTime is after _unlockTime but before putBlockTs (the original timestamp floor)
        // This is exactly where the bug manifests: the mutant stores _unlockTime directly,
        // so if _unlockTime < putBlockTs, unlockTime may be in the past relative to putBlockTs.
        vm.assume(_unlockTime < putBlockTs);
        vm.assume(warpTime >= _unlockTime);
        vm.assume(warpTime < putBlockTs);

        vm.warp(warpTime);

        // Attempt to Collect
        vm.prank(actor);
        // We need to check if Collect reverts
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // Property: if block.timestamp is below the original Put block.timestamp,
        // Collect must fail because unlockTime in the correct contract is at least putBlockTs.
        // The mutant, however, sets unlockTime = _unlockTime, which may be < putBlockTs,
        // allowing Collect to succeed when warpTime >= _unlockTime.
        assertTrue(!ok);
    }
}

