pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 warpTime) public {
        // Bound deposit to be at least MinSum (1 ether) to allow collection
        vm.assume(depositAmount >= 1 ether);
        // Bound collect amount to be at most deposit amount, and at least 1 wei
        vm.assume(collectAmount <= depositAmount);
        vm.assume(collectAmount > 0);
        // warp into the future to ensure unlock time is passed
        vm.warp(warpTime);
        // Use this contract as the actor
        vm.deal(address(this), depositAmount);
        c.Put{value: depositAmount}(uint256(block.timestamp - 1));
        // Record contract balance before collect
        uint256 contractBalanceBefore = address(c).balance;
        c.Collect(collectAmount);
        uint256 contractBalanceAfter = address(c).balance;
        // General rule: contract balance must be reduced by exactly collectAmount after successful Collect
        // In the reference contract: acc.balance -= collectAmount, so contract.balance -= collectAmount.
        // In the buggy contract: acc.balance = 0, but contract balance is still decreased by collectAmount (sent to caller),
        // making the balance reduction larger than collectAmount if there was more than collectAmount deposited.
        // However, the rule here is: the reduction in contract balance equals collectAmount.
        // For the reference, this holds. For the bug, if depositAmount > collectAmount, balance becomes 0,
        // but contract balance reduction is still collectAmount, so the rule STILL HOLDS? Wait.
        // Let's reason: In reference, acc.balance = depositAmount - collectAmount, contract.balance = initial - collectAmount.
        // In bug, acc.balance = 0, contract.balance = initial - collectAmount (since collectAmount is sent).
        // The contract balance reduction is collectAmount in both cases, so that rule doesn't distinguish.
        // We need a rule about the state variable Acc[user].balance.
        // Observation: In reference, Acc[msg.sender].balance becomes depositAmount - collectAmount.
        // In bug, Acc[msg.sender].balance becomes 0.
        // So the rule: After Collect, the user's balance must be depositAmount - collectAmount.
        // We can read Acc[user].balance via the public getter.
        assertEq(c.Acc(address(this)).balance, depositAmount - collectAmount);
    }
}

